-- =============================================================================
-- 0001 core schema — the approved e-commerce ERD, implemented as supplied.
-- PostgreSQL 17. Quoted lowercase identifiers equal their unquoted form.
-- Forward-only migration: never edit an applied file, add a new one.
-- =============================================================================

CREATE TABLE "customer" (
  "customer_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "first_name" varchar(100) NOT NULL,
  "last_name" varchar(100) NOT NULL,
  "phone" varchar(30),
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "country" (
  "country_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "country_name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "address" (
  "address_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" int NOT NULL,
  "address_line1" varchar(255) NOT NULL,
  "address_line2" varchar(255),
  "city" varchar(100) NOT NULL,
  "region" varchar(100),
  "postal_code" varchar(20),
  "country_id" int NOT NULL,
  "is_default" boolean NOT NULL DEFAULT false
);

CREATE TABLE "payment_type" (
  "payment_type_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type_name" varchar(50) UNIQUE NOT NULL
);

CREATE TABLE "payment_method" (
  "payment_method_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" int NOT NULL,
  "payment_type_id" int NOT NULL,
  "provider" varchar(50) NOT NULL,
  "provider_token" varchar(255) NOT NULL,
  "card_brand" varchar(30),
  "last_four" char(4),
  "expiry_month" int,
  "expiry_year" int,
  "is_default" boolean NOT NULL DEFAULT false
);

CREATE TABLE "category" (
  "category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_name" varchar(100) NOT NULL,
  "parent_category_id" int
);

CREATE TABLE "product" (
  "product_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_name" varchar(255) NOT NULL,
  "description" text,
  "brand" varchar(100),
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "product_category" (
  "product_id" int NOT NULL,
  "category_id" int NOT NULL,
  PRIMARY KEY ("product_id", "category_id")
);

CREATE TABLE "product_variant" (
  "variant_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "sku" varchar(50) UNIQUE NOT NULL,
  "price" decimal(10,2) NOT NULL,
  "qty_in_stock" int NOT NULL DEFAULT 0
);

CREATE TABLE "product_option" (
  "option_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "option_name" varchar(50) NOT NULL
);

CREATE TABLE "product_option_value" (
  "option_value_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "option_id" int NOT NULL,
  "value_name" varchar(50) NOT NULL
);

CREATE TABLE "variant_option_value" (
  "variant_id" int NOT NULL,
  "option_id" int NOT NULL,
  "option_value_id" int NOT NULL,
  PRIMARY KEY ("variant_id", "option_id")
);

CREATE TABLE "product_image" (
  "image_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "variant_id" int,
  "image_url" varchar(500) NOT NULL,
  "sort_order" int NOT NULL DEFAULT 1
);

CREATE TABLE "order_status" (
  "order_status_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "status_name" varchar(30) UNIQUE NOT NULL
);

CREATE TABLE "shipping_method" (
  "shipping_method_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "method_name" varchar(50) UNIQUE NOT NULL,
  "price" decimal(10,2) NOT NULL
);

CREATE TABLE "customer_order" (
  "order_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" int NOT NULL,
  "order_status_id" int NOT NULL,
  "order_date" timestamp,
  "shipping_method_id" int,
  "shipping_cost" decimal(10,2),
  "ship_name" varchar(200),
  "ship_address_line1" varchar(255),
  "ship_address_line2" varchar(255),
  "ship_city" varchar(100),
  "ship_region" varchar(100),
  "ship_postal_code" varchar(20),
  "ship_country" varchar(100),
  "subtotal" decimal(10,2),
  "discount_total" decimal(10,2),
  "order_total" decimal(10,2),
  "created_at" timestamp NOT NULL DEFAULT now(),
  "updated_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "order_line" (
  "order_line_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" int NOT NULL,
  "variant_id" int NOT NULL,
  "quantity" int NOT NULL,
  "product_name" varchar(255),
  "sku" varchar(50),
  "option_summary" varchar(255),
  "unit_price" decimal(10,2),
  "discount_amount" decimal(10,2)
);

CREATE TABLE "payment" (
  "payment_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" int NOT NULL,
  "payment_method_id" int,
  "provider_reference" varchar(255) NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "payment_status" varchar(30) NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT now()
);

CREATE TABLE "promotion" (
  "promotion_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "promotion_name" varchar(100) NOT NULL,
  "description" text,
  "discount_type" varchar(20) NOT NULL,
  "discount_value" decimal(10,2) NOT NULL,
  "start_date" timestamp NOT NULL,
  "end_date" timestamp NOT NULL
);

CREATE TABLE "promotion_product" (
  "promotion_id" int NOT NULL,
  "product_id" int NOT NULL,
  PRIMARY KEY ("promotion_id", "product_id")
);

CREATE TABLE "review" (
  "review_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_line_id" int UNIQUE NOT NULL,
  "rating" int NOT NULL,
  "comment" text,
  "created_at" timestamp NOT NULL DEFAULT now()
);

-- Unique business rules stated on the ERD.
CREATE UNIQUE INDEX uq_product_option_name ON "product_option" ("product_id", "option_name");
CREATE UNIQUE INDEX uq_product_option_value_name ON "product_option_value" ("option_id", "value_name");
CREATE UNIQUE INDEX uq_option_value_option ON "product_option_value" ("option_value_id", "option_id");
CREATE UNIQUE INDEX uq_order_line_variant ON "order_line" ("order_id", "variant_id");

COMMENT ON COLUMN "customer"."email" IS 'Used to log in';
COMMENT ON COLUMN "customer"."password_hash" IS 'Hashed by the application, never plain text';
COMMENT ON COLUMN "address"."is_default" IS 'One default per customer (partial unique index)';
COMMENT ON COLUMN "payment_type"."type_name" IS 'Card, PayPal, etc.';
COMMENT ON COLUMN "payment_method"."provider" IS 'e.g. Stripe';
COMMENT ON COLUMN "payment_method"."provider_token" IS 'Token from the payment provider. Card numbers are never stored';
COMMENT ON COLUMN "payment_method"."is_default" IS 'One default per customer (partial unique index)';
COMMENT ON COLUMN "category"."parent_category_id" IS 'NULL = top-level category';
COMMENT ON COLUMN "product_option"."option_name" IS 'e.g. Size, Colour';
COMMENT ON COLUMN "product_option_value"."value_name" IS 'e.g. S, M, L, Black';
COMMENT ON COLUMN "product_image"."variant_id" IS 'NULL = applies to all variants';
COMMENT ON COLUMN "order_status"."status_name" IS 'Cart, Placed, Paid, Shipped, Delivered, Cancelled';
COMMENT ON COLUMN "shipping_method"."method_name" IS 'Standard, Express, etc.';
COMMENT ON COLUMN "customer_order"."order_status_id" IS 'Status 1 (Cart) = order not yet placed';
COMMENT ON COLUMN "customer_order"."order_date" IS 'NULL while the order is a cart';
COMMENT ON COLUMN "customer_order"."shipping_cost" IS 'Copied at checkout';
COMMENT ON COLUMN "customer_order"."ship_name" IS 'Shipping address fields are copied at checkout';
COMMENT ON COLUMN "order_line"."product_name" IS 'Copied at checkout';
COMMENT ON COLUMN "order_line"."sku" IS 'Copied at checkout';
COMMENT ON COLUMN "order_line"."option_summary" IS 'e.g. Black / M, copied at checkout';
COMMENT ON COLUMN "order_line"."unit_price" IS 'Copied at checkout';
COMMENT ON COLUMN "order_line"."discount_amount" IS 'Promotion discount applied at checkout';
COMMENT ON COLUMN "payment"."provider_reference" IS 'Transaction ID from the payment provider';
COMMENT ON COLUMN "payment"."payment_status" IS 'e.g. Succeeded, Failed, Refunded';
COMMENT ON COLUMN "promotion"."discount_type" IS 'Percentage or Fixed';
COMMENT ON COLUMN "review"."order_line_id" IS 'Only purchased items can be reviewed, one review per purchase';
COMMENT ON COLUMN "review"."rating" IS 'CHECK (rating BETWEEN 1 AND 5)';

ALTER TABLE "address" ADD FOREIGN KEY ("customer_id") REFERENCES "customer" ("customer_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "address" ADD FOREIGN KEY ("country_id") REFERENCES "country" ("country_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "payment_method" ADD FOREIGN KEY ("customer_id") REFERENCES "customer" ("customer_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "payment_method" ADD FOREIGN KEY ("payment_type_id") REFERENCES "payment_type" ("payment_type_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "category" ADD FOREIGN KEY ("parent_category_id") REFERENCES "category" ("category_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "product_category" ADD FOREIGN KEY ("product_id") REFERENCES "product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "product_category" ADD FOREIGN KEY ("category_id") REFERENCES "category" ("category_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "product_variant" ADD FOREIGN KEY ("product_id") REFERENCES "product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "product_option" ADD FOREIGN KEY ("product_id") REFERENCES "product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "product_option_value" ADD FOREIGN KEY ("option_id") REFERENCES "product_option" ("option_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "variant_option_value" ADD FOREIGN KEY ("variant_id") REFERENCES "product_variant" ("variant_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "variant_option_value" ADD FOREIGN KEY ("option_value_id", "option_id") REFERENCES "product_option_value" ("option_value_id", "option_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "product_image" ADD FOREIGN KEY ("product_id") REFERENCES "product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "product_image" ADD FOREIGN KEY ("variant_id") REFERENCES "product_variant" ("variant_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "customer_order" ADD FOREIGN KEY ("customer_id") REFERENCES "customer" ("customer_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "customer_order" ADD FOREIGN KEY ("order_status_id") REFERENCES "order_status" ("order_status_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "customer_order" ADD FOREIGN KEY ("shipping_method_id") REFERENCES "shipping_method" ("shipping_method_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "order_line" ADD FOREIGN KEY ("order_id") REFERENCES "customer_order" ("order_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "order_line" ADD FOREIGN KEY ("variant_id") REFERENCES "product_variant" ("variant_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "payment" ADD FOREIGN KEY ("order_id") REFERENCES "customer_order" ("order_id") DEFERRABLE INITIALLY IMMEDIATE;
